class DuelQuestion {
  final String type;
  final String question;
  final String? codeSnippet;
  final List<String>? options;
  final String answer;

  DuelQuestion({
    required this.type,
    required this.question,
    this.codeSnippet,
    this.options,
    required this.answer,
  });
}

